// An ungranted package that receives an attenuated handle and uses it. It holds
// no fs grant of its own; its only authority over ./shared is whatever handle
// it is handed -- bounded by the handle's scope, never the grantor's full
// authority, never the recipient's own grants (it has none).

export function readWith(handle, relPath) {
  // Possession-checked use: open a synchronous window on the handle, then read.
  // The read attributes to recipient-dep (nearest frame); its own grants would
  // deny, so the handle authorizes it iff the path is within the handle scope.
  return handle.use(() => Deno.readTextFileSync(relPath));
}

export function readWithout(relPath) {
  // No handle window: recipient has no authority, so this denies.
  return Deno.readTextFileSync(relPath);
}

export function readHolding(handle, relPath) {
  // Merely *holding* the carrier confers nothing; authority is scoped to an
  // active use() window. Reading outside the window denies.
  void handle;
  return Deno.readTextFileSync(relPath);
}

export function tryWiden(handle) {
  // scoped() only narrows: a capability wider than the parent handle's is
  // denied (over-broad re-widening).
  return handle.scoped("fs:read:./shared");
}

export function scopeDeeper(handle) {
  // A genuine narrowing: derive a child handle within the parent's scope.
  return handle.scoped("fs:read:./shared/pub/sub");
}
